import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BymHWfgO.js";const p=JSON.parse('{"title":"Say It Out Loud: Spoken Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),r={name:"14-say-it-out-loud.md"};function i(s,e,u,l,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="say-it-out-loud-spoken-scripts" tabindex="-1">Say It Out Loud: Spoken Scripts <a class="header-anchor" href="#say-it-out-loud-spoken-scripts" aria-label="Permalink to &quot;Say It Out Loud: Spoken Scripts&quot;">​</a></h1><h2 id="feature-1-continuous-batching" tabindex="-1">Feature 1: Continuous Batching <a class="header-anchor" href="#feature-1-continuous-batching" aria-label="Permalink to &quot;Feature 1: Continuous Batching&quot;">​</a></h2><blockquote><p>&quot;I built the continuous batching engine to solve the fundamental GPU underutilization problem in LLM serving. In traditional batching, if one request generates 10 tokens and another generates 500 tokens, the GPU sits idle on 90% of the batch for hundreds of iterations. My continuous batcher steps through generation at the individual token level. At every forward pass, it evaluates the remaining token budget, evicts requests that reached an EOS token, and dynamically merges new incoming prompts into the active batch. This boosted aggregate token throughput by over 3x under dynamic real-world workloads.&quot;</p></blockquote><h2 id="feature-2-paged-kv-cache" tabindex="-1">Feature 2: Paged KV-Cache <a class="header-anchor" href="#feature-2-paged-kv-cache" aria-label="Permalink to &quot;Feature 2: Paged KV-Cache&quot;">​</a></h2><blockquote><p>&quot;To prevent out-of-memory crashes during multi-user generation, I designed a Paged KV-Cache allocator modeled after operating system virtual memory paging. In standard self-attention, you have to pre-allocate contiguous GPU memory for the maximum possible sequence length—say, 4,096 tokens—even if the user only generates 50 tokens. My allocator divides GPU memory into fixed 16-token physical pages. As a request generates tokens, logical sequence offsets are mapped to physical pages via a page table. When generation completes, all pages are instantly returned to the free list. This eliminated external memory fragmentation and increased our maximum concurrent batch size by 400%.&quot;</p></blockquote>',5)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
